/**
 * Provided -- do not edit.
 *
 * hp is private: subclasses cannot reach in and set it. The only way damage is
 * ever applied is takeHit, which is final and asks the subclass for its armour.
 */
abstract class Creature {

    private final String name;
    private int hp;

    protected Creature(String name, int hp) {
        this.name = name;
        this.hp = Math.max(0, hp);
    }

    public final String getName() {
        return name;
    }

    public final int getHp() {
        return hp;
    }

    public final boolean isAlive() {
        return hp > 0;
    }

    public final void takeHit(int rawDamage) {
        int actual = Math.max(0, rawDamage - armour());
        hp = Math.max(0, hp - actual);
    }

    /** How hard this creature hits right now. */
    public abstract int attackPower();

    /** How much damage this creature shrugs off. The default is none. */
    protected int armour() {
        return 0;
    }

    @Override
    public String toString() {
        return name + "(" + hp + ")";
    }
}

