public class CreatureArenaTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            Creature knight = new CreatureArena.Knight("kay");
            Creature dragon = new CreatureArena.Dragon("fafnir");

            check("knight attack", 7, knight.attackPower());
            check("dragon attack while healthy", 12, dragon.attackPower());
            check("knight toString", "kay(30)", knight.toString());

            knight.takeHit(2);
            check("armour absorbs a weak blow", 30, knight.getHp());

            dragon.takeHit(22);
            check("dragon armour reduces damage by one", 19, dragon.getHp());
            check("a wounded dragon enrages", 24, dragon.attackPower());

            knight.takeHit(500);
            check("hp never goes below zero", 0, knight.getHp());
            check("a creature at zero hp is dead", false, knight.isAlive());

            Creature[] army = { new CreatureArena.Knight("a"), new CreatureArena.Dragon("b"), null };
            check("totalPower over mixed types", 19, CreatureArena.totalPower(army));
            check("totalPower of null", 0, CreatureArena.totalPower(null));
            check("totalPower of an empty army", 0, CreatureArena.totalPower(new Creature[0]));

            check("knight versus dragon",
                    "fafnir wins in 4 rounds",
                    CreatureArena.duel(new CreatureArena.Knight("kay"), new CreatureArena.Dragon("fafnir")));
            check("knight versus knight",
                    "kay wins in 8 rounds",
                    CreatureArena.duel(new CreatureArena.Knight("kay"), new CreatureArena.Knight("bors")));
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- expected none but got " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

