public class CreatureArena {

    public static class Knight extends Creature {

        public Knight(String name) {
            super(name, 30);
        }

        @Override
        public int attackPower() {
            return 7;
        }

        @Override
        protected int armour() {
            return 3;
        }
    }

    public static class Dragon extends Creature {

        public Dragon(String name) {
            super(name, 40);
        }

        @Override
        public int attackPower() {
            return getHp() < 20 ? 24 : 12;
        }

        @Override
        protected int armour() {
            return 1;
        }
    }

    public static int totalPower(Creature[] army) {
        if (army == null) {
            return 0;
        }
        int total = 0;
        for (Creature creature : army) {
            if (creature != null) {
                total += creature.attackPower();
            }
        }
        return total;
    }

    public static String duel(Creature a, Creature b) {
        for (int round = 1; round <= 100; round++) {
            b.takeHit(a.attackPower());
            if (!b.isAlive()) {
                return a.getName() + " wins in " + round + " rounds";
            }
            a.takeHit(b.attackPower());
            if (!a.isAlive()) {
                return b.getName() + " wins in " + round + " rounds";
            }
        }
        return "draw after 100 rounds";
    }
}
